# Parte C: Sample Editor, mixer, flusso ADR, sala di registrazione, sincronia, esportazione, preferenze.
from content_a import A, h2, h3, h4, p, ul, ol, note, tip, warn, table, fig, menu

# ======================================================================================================================
h2('Il Sample Editor', 'The Sample Editor')
p('Con un **doppio clic su un clip** (con lo strumento Selezione) oppure con **Modifica > Sample Editor (clip selezionato)** si apre una finestra dedicata a quel clip, con la forma d\'onda a tutta larghezza, lo zoom, la selezione di una porzione e le elaborazioni sulla sola selezione.',
  'A **double-click on a clip** (with the Select tool) or **Edit > Sample Editor (selected clip)** opens a window dedicated to that clip, with the waveform at full width, zoom, selection of a portion and processing of the selection only.')
fig('editor_wave', 'Il Sample Editor con una porzione selezionata.', 'The Sample Editor with a portion selected.', maxw=1500, base_w=1960, callouts=[
    (133, 102, 't', ('**SPETTROGRAMMA**: alterna forma d\'onda e spettrogramma.', '**SPECTROGRAM**: switches between waveform and spectrogram.')),
    (312, 102, 't', ('**TUTTO**: seleziona tutto il clip (come il doppio clic).', '**ALL**: selects the whole clip (like a double-click).')),
    (430, 102, 't', ('**ADATTA**: mostra tutto il clip.', '**FIT**: shows the whole clip.')),
    (565, 102, 't', ('**ASCOLTA**: riproduce in ciclo la selezione (o tutto il clip); ferma con la barra spaziatrice.', '**LISTEN**: plays the selection (or the whole clip) in a loop; stop with the space bar.')),
    (754, 102, 't', ('**ATTACCHI**: mostra i punti di attacco (hitpoint); la barra accanto regola la sensibilità.', '**HITPOINTS**: shows the hitpoints; the slider next to it sets the sensitivity.')),
    (1109, 102, 't', ('**DIVIDI**: divide il clip ai punti di attacco mostrati.', '**SPLIT**: splits the clip at the hitpoints shown.')),
    (95, 166, 'd', ('**GUADAGNO**: cambia di tanti dB quanti scritti nella casella accanto.', '**GAIN**: changes the selection by the dB written in the box next to it.')),
    (376, 166, 'd', ('**NORMALIZZA**: porta il picco della selezione a −1 dBFS.', '**NORMALISE**: brings the selection\'s peak to −1 dBFS.')),
    (538, 166, 'd', ('**FADE IN / FADE OUT**: dissolvenza in crescendo o in calando sulla selezione.', '**FADE IN / FADE OUT**: fades the selection in or out.')),
    (826, 166, 'd', ('**SILENZIO**: azzera la selezione (taglia un colpo di tosse, un click).', '**SILENCE**: silences the selection (cuts out a cough, a click).')),
    (972, 166, 'd', ('**REVERSE**: inverte la selezione nel tempo.', '**REVERSE**: reverses the selection in time.')),
    (1113, 166, 'd', ('**INVERTI**: inverte la polarità della selezione.', '**INVERT**: inverts the selection\'s polarity.')),
    (1259, 166, 'd', ('**TOGLI DC**: toglie l\'offset di continua dalla selezione.', '**REMOVE DC**: removes the DC offset from the selection.')),
    (770, 520, 'd', ('**Selezione**: trascina sulla forma d\'onda; la durata compare in basso. Un clic sposta la testina.', '**Selection**: drag on the waveform; the length appears at the bottom. A click moves the playhead.')),
    (900, 267, 'd', ('Righello in secondi: la rotella scorre, **Cmd + rotella** (o pizzico) fa lo zoom.', 'Ruler in seconds: the wheel scrolls, **Cmd + wheel** (or pinch) zooms.')),
])
fig('editor_spectro', 'La vista a spettrogramma: il tempo in orizzontale, la frequenza (60 Hz – 12 kHz, scala logaritmica) in verticale e il livello in colore.', 'The spectrogram view: time horizontally, frequency (60 Hz – 12 kHz, logarithmic scale) vertically and level in colour.', maxw=1300, base_w=1960)
ul(('Ogni elaborazione scrive un **file nuovo** (nella cartella Elaborati) e sostituisce l\'audio del clip senza cambiarne posizione e durata; **Modifica > Annulla** la riporta com\'era. Inviluppo e punto di sincronia seguono il nuovo file.',
    'Every processing writes a **new file** (in the Elaborati folder) and replaces the clip\'s audio without changing its position and length; **Edit > Undo** brings it back. Envelope and sync point follow the new file.'),
   ('Lo spettrogramma aiuta a vedere sibilanti, rumori di fondo, colpi di vento e click che l\'orecchio fatica a localizzare.', 'The spectrogram helps to see sibilance, background noise, wind bursts and clicks that the ear finds hard to locate.'))

# ======================================================================================================================
h2('Mixer ed elaborazione del suono', 'Mixer and sound processing')
h3('Volume, pan, mute, solo e mandate', 'Volume, pan, mute, solo and sends')
ul(('**Fader**: da −∞ a +6 dB; doppio clic = 0 dB. Il **pan** è una manopola da L a R. Il **guadagno in ingresso** (Trim) di ogni traccia si regola dalla manopola nell\'intestazione della traccia (dove c\'è spazio).', '**Fader**: from −∞ to +6 dB; double-click = 0 dB. The **pan** is a knob from L to R. Each track\'s **input gain** (Trim) is set with the knob in the track header (where there is room).'),
   ('**M**, **S**, **Ø**: mute, solo e inversione di polarità. Con almeno un solo attivo suonano soltanto le tracce in solo. Il pulsante **M** in alto a sinistra nella timeline toglie tutti i mute, **S** tutti i solo.', '**M**, **S**, **Ø**: mute, solo and polarity inversion. With at least one solo active only the soloed tracks play. The **M** button at the top left of the timeline clears all mutes, **S** all solos.'),
   ('**SEND A / SEND B**: mandate (dopo il fader) ai due ritorni effetti **FX A** e **FX B**, che hanno i loro inserti, fader e mute. Servono per un riverbero o un\'eco condivisi da più tracce.', '**SEND A / SEND B**: sends (post-fader) to the two effect returns **FX A** and **FX B**, which have their own inserts, fader and mute. They are for a reverb or echo shared by several tracks.'),
   ('**Uscita della traccia** (pulsante MASTER): la traccia può andare al master oppure a uno dei quattro bus (Dialoghi, M&E, Effetti, Guida); i bus hanno un fader e gli inserti propri.', '**Track output** (MASTER button): the track can go to the master or to one of the four buses (Dialogue, M&E, Effects, Guide); the buses have their own fader and inserts.'))
h3('L\'editor di EQ e compressore', 'The EQ and compressor editor')
p('Il pulsante **EQ** di un canale apre l\'editor della traccia: un **EQ a quattro bande** con grafico interattivo e un **compressore**. Il tipo di traccia (Dialoghi, M&E, Effetti, Guida) si può scegliere anche qui.',
  'A channel\'s **EQ** button opens the track\'s editor: a **4-band EQ** with an interactive graph and a **compressor**. The track type (Dialogue, M&E, Effects, Guide) can also be chosen here.')
fig('eq_editor', 'L\'editor di EQ e compressore di una traccia.', 'A track\'s EQ and compressor editor.', maxw=1200)
ul(('**Grafico**: trascina i punti per cambiare frequenza e guadagno; la rotella su un punto cambia la larghezza (Q); doppio clic azzera il guadagno.', '**Graph**: drag the points to change frequency and gain; the wheel on a point changes the width (Q); double-click resets the gain.'),
   ('**Bande 1–4**: tipo (Campana/Bell, Shelf basso/Low shelf, Shelf alto/High shelf, Passa-alto/High-pass, Passa-basso/Low-pass), frequenza, guadagno e Q; la casella attiva o esclude ogni banda, **EQ ON** tutto l\'equalizzatore.', '**Bands 1–4**: type (Bell, Low shelf, High shelf, High-pass, Low-pass), frequency, gain and Q; the checkbox enables or bypasses each band, **EQ ON** the whole equaliser.'),
   ('**Compressore**: soglia, rapporto, attacco, rilascio e guadagno di compensazione.', '**Compressor**: threshold, ratio, attack, release and make-up gain.'))
h3('Limiter di traccia e master', 'Track and master limiter')
ul(('**LIM** (traccia): limiter dopo il fader, tetto regolabile dalla freccia accanto; aggiunge 3 ms di latenza (compensata) e si accende in giallo quando interviene.', '**LIM** (track): limiter after the fader, ceiling set with the arrow beside it; it adds 3 ms of latency (compensated) and lights up yellow when it acts.'),
   ('**LIMITER** (master): attacco anticipato 3 ms e rilascio 80 ms; nessun picco supera il tetto (manopola, doppio clic −1 dB).', 'Master **LIMITER**: 3 ms look-ahead and 80 ms release; no peak exceeds the ceiling (knob, double-click −1 dB).'),
   ('**MONO** e **DIM** sono controlli d\'ascolto: non influiscono su esportazione e misure.', '**MONO** and **DIM** are monitoring controls: they do not affect export and measurements.'))
h3('Inserti: effetti integrati e plug-in VST3', 'Inserts: built-in effects and VST3 plug-ins')
p('Ogni canale (e il master, i ritorni FX e i bus) ha quattro inserti. Il clic su «+ Inserisci» (o **Traccia > Aggiungi plug-in VST3 alla traccia selezionata**, tasto P) apre il **navigatore degli effetti**, con una casella di ricerca per nome o categoria e le schede *Tutti*, *Integrati* e *VST3*.',
  'Each channel (and the master, the FX returns and the buses) has four inserts. Clicking "+ Insert" (or **Track > Add VST3 plug-in to the selected track**, key P) opens the **effect browser**, with a search box for name or category and the tabs *All*, *Built-in* and *VST3*.')
fig('dlg_plugins', 'Il navigatore degli effetti.', 'The effect browser.', maxw=760)
ul(('**Effetti integrati** (otto): filtro passa-alto/passa-basso 24 dB/ottava, de-esser, gate/expander, compressore multibanda, riverbero a stanza, delay stereo con ping-pong, saturazione, chorus.', '**Built-in effects** (eight): HP/LP filter at 24 dB/octave, de-esser, gate/expander, multiband compressor, room reverb, stereo delay with ping-pong, saturation, chorus.'),
   ('**Plug-in VST3**: il programma li cerca nelle cartelle standard; **Sfoglia…** ne aggiunge una a mano. Lo stato dei plug-in si salva con la sessione. Un plug-in che non si carica resta nell\'elenco con un messaggio d\'errore.', '**VST3 plug-ins**: the program scans the standard folders; **Browse…** adds one by hand. Plug-in state is saved with the session. A plug-in that fails to load stays in the list with an error message.'),
   ('**Compensazione della latenza (PDC)**: il programma allinea le tracce compensando la latenza dei plug-in (**Trasporto > Compensazione latenza plug-in**); un inserto in bypass non conta.', '**Latency compensation (PDC)**: the program aligns the tracks by compensating the plug-ins\' latency (**Transport > Plug-in latency compensation**); a bypassed insert does not count.'),
   ('Il clic destro su un inserto: apri l\'editor, bypass, sposta su/giù, rimuovi.', 'Right-clicking an insert: open the editor, bypass, move up/down, remove.'))
h3('Automazione', 'Automation')
p('Ogni traccia ha curve di automazione per **VOL**, **PAN**, **SEND A** e **SEND B**. Il pulsante AUTO nell\'intestazione della traccia sceglie la modalità (spento, lettura, scrittura) e il pulsante accanto quale curva mostrare. Con lo strumento **Automazione** (U) si aggiungono, spostano ed eliminano i punti; in modalità scrittura i movimenti del fader durante la riproduzione registrano la curva. **Cancella l\'automazione** (menu Traccia) azzera la curva mostrata.',
  'Every track has automation curves for **VOL**, **PAN**, **SEND A** and **SEND B**. The AUTO button in the track header chooses the mode (off, read, write) and the button next to it which curve to show. With the **Automation** tool (U) points are added, moved and deleted; in write mode fader moves during playback record the curve. **Clear automation** (Track menu) resets the displayed curve.')
h3('Misura del loudness e spettro', 'Loudness measurement and spectrum')
ul(('Il pannello di analisi misura il master in tempo reale secondo **ITU-R BS.1770 / EBU R128**: loudness integrato, momentaneo, short-term, loudness range e true peak; sceglie lo standard (EBU R128 −23 LUFS, ATSC A/85 −24, ARIB TR-B32, Netflix dialogo −27, podcast, streaming, audiolibri) e ne mostra obiettivo e tetto.', 'The analysis panel measures the master in real time according to **ITU-R BS.1770 / EBU R128**: integrated, momentary, short-term loudness, loudness range and true peak; it chooses the standard (EBU R128 −23 LUFS, ATSC A/85 −24, ARIB TR-B32, Netflix dialogue −27, podcast, streaming, audiobooks) and shows its target and ceiling.'),
   ('**SOLO PARLATO** limita la misura ai blocchi con parlato (stimato dall\'energia): è il valore su cui si basa la «dialogue gating» delle consegne.', '**SPEECH ONLY** limits the measurement to blocks with speech (estimated from energy): it is the value on which delivery "dialogue gating" is based.'),
   ('La scheda **SPETTRO** mostra uno spettro in tempo reale (FFT 8192 punti, 20 Hz – 20 kHz) con picchi mantenuti (**PICCHI**) e un\'inclinazione di +4,5 dB/ottava (**TILT**) che fa sembrare piatto il rumore rosa.', 'The **SPECTRUM** tab shows a real-time spectrum (8192-point FFT, 20 Hz – 20 kHz) with held peaks (**PEAKS**) and a +4.5 dB/octave tilt (**TILT**) that makes pink noise look flat.'))

# ======================================================================================================================
h2('Il flusso ADR', 'The ADR workflow')
h3('I cue ADR', 'ADR cues')
p('Un **cue** è una battuta da registrare: ha un numero, un **personaggio**, una **scena**, una **bobina**, **ingresso** e **uscita** (timecode), il testo della **battuta**, delle **note** e uno **stato**: *Da registrare*, *Registrato*, *Approvato*, *Da rifare*. Sulla timeline il cue è una zona colorata (con il numero e il personaggio in alto) con maniglie ai bordi.',
  'A **cue** is a line to record: it has a number, a **character**, a **scene**, a **reel**, **in** and **out** (timecode), the text of the **line**, **notes** and a **status**: *To record*, *Recorded*, *Approved*, *To redo*. On the timeline the cue is a coloured zone (with the number and character at the top) with handles on its edges.')
ul(('**Cambiare un cue sulla timeline**: trascina il bordo sinistro o destro della zona per ingresso e uscita, il corpo (la fascia in alto) per spostarlo; si aggancia a clip, marker e testina. Selezionare un cue porta la testina al suo ingresso e lo seleziona nella finestra ADR (e viceversa).', '**Changing a cue on the timeline**: drag the zone\'s left or right edge for in and out, the body (the strip at the top) to move it; it snaps to clips, markers and the playhead. Selecting a cue moves the playhead to its in point and selects it in the ADR window (and vice versa).'),
   ('**Nuovo cue**: *ADR > Nuovo cue dalla regione di loop o dalla testina* (o il pulsante **+ CUE**): crea un cue dalla regione di loop oppure di 4 secondi dalla testina.', '**New cue**: *ADR > New cue from the loop region or the playhead* (or the **+ CUE** button): creates a cue from the loop region, or of 4 seconds from the playhead.'),
   ('**Unire i cue**: nel pannello ADR seleziona due o più cue (Cmd/Ctrl o Maiusc + clic sulle righe) e premi **UNISCI**: diventano un solo cue, dall\'entrata del primo all\'uscita dell\'ultimo, con battute e note riunite e lo stato meno avanzato. I take degli altri cue restano sulla timeline come clip normali. È un solo passo di Annulla.', '**Merging cues**: in the ADR panel select two or more cues (Cmd/Ctrl or Shift + click on the rows) and press **MERGE**: they become a single cue, from the first one\'s in point to the last one\'s out point, with lines and notes combined and the least advanced status. The takes of the other cues stay on the timeline as normal clips. It is a single Undo step.'))
h3('Importare i cue', 'Importing cues')
p('**ADR > Importa cue da Pro Tools / EDL / tabella…** (o il pulsante **IMPORTA…** della finestra ADR, oppure trascinando il file sulle tracce) apre un dialogo che riconosce da solo il formato del file e mostra il timecode e le opzioni.',
  '**ADR > Import cues from Pro Tools / EDL / table…** (or the **IMPORT…** button of the ADR window, or by dragging the file onto the tracks) opens a dialog that recognises the file format by itself and shows the timecode and the options.')
table((('Formato', 'Format'), ('Che cosa viene letto', 'What is read')),
      (('Pro Tools (testo Session Info)', 'Pro Tools (Session Info text)'), ('L\'elenco dei marker (Marker Listing): posizione in timecode assoluto o campioni, nome e commenti. Nei commenti il programma legge `CHARACTER:`, `SCENE:`, `REEL:`, `OUT:`, `DIALOGUE:`, `NOTES:`; un commento libero diventa la battuta e il nome il personaggio.', 'The marker list (Marker Listing): position in absolute timecode or samples, name and comments. In the comments the program reads `CHARACTER:`, `SCENE:`, `REEL:`, `OUT:`, `DIALOGUE:`, `NOTES:`; a free comment becomes the line and the name the character.')),
      (('EDL CMX3600', 'EDL CMX3600'), ('Eventi e locatori con commenti (anche da Nuendo); il formato dei fotogrammi si controlla (un fotogramma impossibile nel formato scelto dà un avviso).', 'Events and locators with comments (also from Nuendo); the frame format is checked (an impossible frame in the chosen format gives a warning).')),
      (('Tabella CSV / TSV', 'CSV / TSV table'), ('Una colonna di timecode più le colonne che il programma riconosce dai titoli (italiani o inglesi): personaggio/attore/ruolo, scena, bobina, ingresso/entrata, uscita, dialogo/battuta/testo, note/commento. Funziona con Nuendo, Fairlight, Resolve e i report ADR.', 'A timecode column plus the columns the program recognises from the headings (Italian or English): character/actor/role, scene, reel, in/start, out, dialogue/line/text, notes/comment. It works with Nuendo, Fairlight, Resolve and ADR reports.')),
      (('Sottotitoli SRT / WebVTT', 'SRT / WebVTT subtitles'), ('Ogni sottotitolo diventa un cue con la sua battuta (senza personaggio: lo si assegna dopo).', 'Each subtitle becomes a cue with its line (without a character: you assign it afterwards).')))
ul(('**Formato timecode e inizio**: il dialogo propone quelli della sessione; i cue prima dell\'inizio della sessione vengono scartati con un avviso.', '**Timecode format and start**: the dialog proposes the session\'s; cues before the session start are discarded with a warning.'),
   ('**Durata predefinita**: per i cue senza uscita.', '**Default length**: for cues without an out point.'),
   ('**Sostituisci i cue esistenti**, **Crea anche un marker per ogni cue** (come le Memory Location) e **Crea una traccia Dialoghi per ogni personaggio** (con ruolo, bus e gruppo «Dialoghi»).', '**Replace the existing cues**, **Also create a marker for each cue** (like Memory Locations) and **Create a Dialogue track for each character** (with role, bus and the "Dialogue" group).'))
h3('La finestra ADR', 'The ADR window')
fig('adr_selected', 'La finestra ADR con il cue 1 selezionato.', 'The ADR window with cue 1 selected.', maxw=1500, base_w=2000, callouts=[
    (112, 110, 't', ('**IMPORTA…**: importa cue da un file.', '**IMPORT…**: imports cues from a file.')),
    (287, 110, 't', ('**+ CUE**: crea un cue dalla regione di loop o dalla testina.', '**+ CUE**: creates a cue from the loop region or the playhead.')),
    (441, 110, 't', ('**ELIMINA**: elimina il cue selezionato.', '**DELETE**: deletes the selected cue.')),
    (639, 110, 't', ('**IMPOSTAZIONI**: apre le impostazioni della sessione.', '**SETTINGS**: opens the session settings.')),
    (866, 110, 't', ('**ESPORTA CSV**: elenco dei cue in CSV (cue sheet).', '**EXPORT CSV**: the cue list as CSV (cue sheet).')),
    (1122, 110, 't', ('**ESPORTA PRO TOOLS**: i cue come testo di marker Pro Tools.', '**EXPORT PRO TOOLS**: the cues as Pro Tools marker text.')),
    (1426, 110, 't', ('**ESPORTA TAKE (BWF)**: i take attivi come file BWF con timecode.', '**EXPORT TAKES (BWF)**: the active takes as BWF files with timecode.')),
    (452, 183, 'd', ('Filtro per **personaggio**: l\'elenco e i pulsanti CUE precedente/successivo seguono il filtro.', 'Filter by **character**: the list and the previous/next CUE buttons follow the filter.')),
    (873, 183, 'd', ('Filtro per **stato** (per esempio «Da registrare»).', 'Filter by **status** (for example "To record").')),
    (1000, 380, 'd', ('**Elenco dei cue**: stato (colore), personaggio, scena, ingresso, uscita, durata, take (attivo/totali) e battuta. Doppio clic su una riga porta la testina al cue.', '**Cue list**: status (colour), character, scene, in, out, length, takes (active/total) and line. Double-click a row to move the playhead to the cue.')),
    (190, 810, 'd', ('**Dettagli** modificabili del cue: personaggio, scena, bobina, ingresso e uscita (TC), stato, battuta e note.', 'Editable **details** of the cue: character, scene, reel, in and out (TC), status, line and notes.')),
    (167, 1043, 'd', ('**Take** (T1, T2…) con le stelle: il blu è quello attivo.', '**Takes** (T1, T2…) with their stars: blue is the active one.')),
    (305, 1111, 'd', ('**Valutazione** a 1–5 stelle del take scelto (un secondo clic sulla stessa stella la toglie).', '**Rating** 1–5 stars of the chosen take (a second click on the same star removes it).')),
    (1324, 1041, 'd', ('**ORIGINALE**: ascolta la battuta originale (l\'audio di produzione, senza i take ADR) con il video in sincronia.', '**ORIGINAL**: listen to the original line (production audio, without the ADR takes) with the video in sync.')),
    (1514, 1041, 'd', ('**ASCOLTA**: ascolta da solo il take scelto, con il video in sincronia.', '**LISTEN**: listen to the chosen take alone, with the video in sync.')),
    (1686, 1041, 'd', ('**ATTIVA**: rende attivo il take scelto: è quello che suona nel mix e viene esportato.', '**ACTIVATE**: makes the chosen take active: it is the one that plays in the mix and is exported.')),
    (1876, 1041, 'd', ('**ELIMINA TAKE**: elimina il take scelto (annullabile).', '**DELETE TAKE**: deletes the chosen take (undoable).')),
    (1364, 1109, 'd', ('**TIENI QUESTO**: tiene il take scelto (lo rende attivo) e scarta tutti gli altri del cue.', '**KEEP THIS**: keeps the chosen take (makes it active) and discards all the others of the cue.')),
    (1591, 1109, 'd', ('**SCARTA**: scarta il take (non suona più e non conta) o lo ripristina; non lo elimina dal disco.', '**DISCARD**: discards the take (it no longer plays or counts) or restores it; it does not delete it from disk.')),
    (1839, 1109, 'd', ('**ELIMINA SCARTATE**: elimina definitivamente i take scartati del cue (con Maiusc, di tutti i cue).', '**DELETE DISCARDED**: permanently deletes the cue\'s discarded takes (with Shift, of all cues).')),
    (1200, 1183, 'd', ('**REGISTRA SU**: la traccia su cui registrare (di norma una traccia Dialoghi del personaggio).', '**RECORD ON**: the track to record on (normally the character\'s Dialogue track).')),
    (1473, 1181, 'd', ('**< CUE / CUE >**: cue precedente e successivo (Cmd + Maiusc + ←/→).', '**< CUE / CUE >**: previous and next cue (Cmd + Shift + ←/→).')),
    (1839, 1181, 'd', ('**REGISTRA CUE**: pre-roll, bip, sbarra sul video e punch automatico sul cue selezionato.', '**RECORD CUE**: pre-roll, beeps, streamer over the picture and automatic punch on the selected cue.')),
])
h3('Registrare un cue', 'Recording a cue')
ol(('Imposta in *Impostazioni sessione* pre-roll, post-roll e numero di bip; scegli l\'ingresso in *File > Impostazioni audio*.', 'In *Session settings* set pre-roll, post-roll and number of beeps; choose the input in *File > Audio settings*.'),
   ('Nella finestra ADR seleziona il cue e, in **REGISTRA SU**, la traccia di destinazione.', 'In the ADR window select the cue and, in **RECORD ON**, the destination track.'),
   ('Premi **REGISTRA CUE**. Il programma porta la testina al pre-roll, mostra il video (se era nascosto) e parte: **conto alla rovescia** con i bip (nelle cuffie del direttore e in uscita), **barra ambra** con il numero grande dei secondi sul video, poi **barra rossa** e cornice rossa lampeggiante per la durata del cue, con la battuta in sovrimpressione.', 'Press **RECORD CUE**. The program moves the playhead to the pre-roll, shows the video (if it was hidden) and starts: **countdown** with the beeps (in the director\'s headphones and at the output), an **amber bar** with the big number of seconds over the picture, then a **red bar** and a flashing red frame for the length of the cue, with the line as an overlay.'),
   ('La registrazione è un **punch automatico**: scrive solo fra ingresso e uscita del cue. Al termine nasce un **nuovo take** (T1, T2…) su quella traccia, compensando la latenza della scheda, e il cue passa a *Registrato*. Ripeti quante volte vuoi: i take si sovrappongono e suona solo quello attivo. Mentre registri, la **forma d\'onda si disegna sulla traccia in tempo reale** dentro il blocco rosso. Durante la registrazione del cue **non suonano i take già registrati** (di nessun cue): in cuffia e in uscita si sentono solo la guida e l\'audio originale.', 'The recording is an **automatic punch**: it writes only between the cue\'s in and out points. At the end a **new take** (T1, T2…) is created on that track, compensating for the interface\'s latency, and the cue becomes *Recorded*. Repeat as often as you like: takes overlap and only the active one plays. While you record, the **waveform is drawn on the track in real time** inside the red block. While the cue is being recorded **the takes already recorded do not play** (of any cue): in the headphones and at the output you hear only the guide and the original audio.'),
   ('**Fermare**: *ADR > Ferma la registrazione del cue* (Cmd + Maiusc + R) o il pulsante di stop.', '**Stopping**: *ADR > Stops the recording of the cue* (Cmd + Shift + R) or the stop button.'))
note('I bip si sentono sempre, anche con DIM acceso: vengono aggiunti dopo i controlli d\'ascolto. Se il cue è vicinissimo all\'inizio e non c\'è posto per tutto il pre-roll, i bip si avvicinano invece di sparire.',
     'The beeps are always heard, even with DIM on: they are added after the monitoring controls. If the cue is very close to the start and there is no room for the whole pre-roll, the beeps get closer together instead of disappearing.')
h3('Scegliere il take migliore', 'Choosing the best take')
ul(('Seleziona il cue e scegli un take con i pulsanti **T1, T2…** (la stella accanto è la valutazione). **ASCOLTA** lo ascolta da solo; **ORIGINALE** fa il confronto con la battuta originale.', 'Select the cue and choose a take with the **T1, T2…** buttons (the star next to it is the rating). **LISTEN** plays it alone; **ORIGINAL** compares it with the original line.'),
   ('Dai le **stelle**; al termine **TIENI QUESTO** rende attivo il migliore e scarta gli altri; **SCARTA** nasconde un take senza cancellarlo; **ELIMINA SCARTATE** cancella.', 'Give **stars**; at the end **KEEP THIS** makes the best one active and discards the others; **DISCARD** hides a take without deleting it; **DELETE DISCARDED** deletes.'),
   ('Lo stato del cue (*Registrato*, *Approvato*, *Da rifare*) si cambia dai dettagli; il **Controllo della sessione** segnala i cue ancora da registrare, da rifare, o con più take da scegliere.', 'The cue\'s status (*Recorded*, *Approved*, *To redo*) is changed in the details; the **Session check** reports cues still to record, to redo, or with several takes to choose from.'),
   ('Nella timeline i take non attivi sono grigi; il clic destro su un clip ADR offre *attiva il take*, *elimina il take* e *adatta alla durata del cue (time-stretch)*.', 'In the timeline inactive takes are grey; right-clicking an ADR clip offers *activate the take*, *delete the take* and *fit to the cue\'s length (time-stretch)*.'))
h3('Importare take già registrati', 'Importing takes already recorded')
p('**ADR > Importa take registrati da una cartella…** legge una cartella di file con nomi come `Cue012_Marco_Take2_BEST.wav`: associa ogni file al cue dal numero, controlla il personaggio, riconosce il numero del take e la parola «BEST» (il take scelto) e posiziona il file sul timecode scritto nel BWF (altrimenti sull\'ingresso del cue). I file già presenti non vengono duplicati e le anomalie sono riportate in un elenco.',
  '**ADR > Import recorded takes from a folder…** reads a folder of files named like `Cue012_Marco_Take2_BEST.wav`: it matches each file to the cue by number, checks the character, recognises the take number and the word "BEST" (the chosen take) and places the file at the timecode written in the BWF (otherwise at the cue\'s in point). Files already present are not duplicated and anomalies are reported in a list.')
h3('Esportare cue e take', 'Exporting cues and takes')
ul(('**Esporta cue sheet (CSV)** e **Esporta cue come marker Pro Tools (testo)**: si rileggono con gli stessi cue.', '**Export cue sheet (CSV)** and **Export cues as Pro Tools markers (text)**: they read back with the same cues.'),
   ('**Esporta take attivi (BWF con timecode)**: un file BWF a 24 bit per ogni cue con take attivo, con il timecode (time reference) della posizione sulla timeline, pronto da piazzare in Pro Tools.', '**Export active takes (BWF with timecode)**: one 24-bit BWF file for every cue with an active take, with the timecode (time reference) of the position on the timeline, ready to place in Pro Tools.'),
   ('**Foglio cue e copione per personaggio (stampabile)**: una pagina HTML con il riepilogo di tutti i cue e un copione per ogni personaggio; si apre nel browser, da cui si stampa o si salva in PDF.', '**Cue sheet and script per character (printable)**: an HTML page with the summary of all cues and one script per character; it opens in the browser, from where it can be printed or saved as PDF.'))
h3('La sala di registrazione', 'The recording room')
p('Tre strumenti pensati per la sala di doppiaggio, con l\'attore dentro e il direttore in regia.',
  'Three tools designed for the dubbing room, with the actor inside and the director in the booth.')
h4('Lettore copione per l\'attore', 'Script reader for the actor')
p('**ADR > Lettore copione per l\'attore** apre una finestra (da spostare sullo schermo dell\'attore) con il personaggio, scena e bobina, il timecode, la **battuta in grande** con un\'indicazione «PRONTO…» prima dell\'ingresso, una barra di avanzamento e le due battute successive. **A− / A+** (o la rotella con Cmd) cambiano la dimensione del testo.',
  '**ADR > Script reader for the actor** opens a window (to be moved to the actor\'s screen) with the character, scene and reel, the timecode, the **line in large type** with a "READY…" indication before the in point, a progress bar and the next two lines. **A− / A+** (or the wheel with Cmd) change the text size.')
fig('script', 'Il lettore copione per l\'attore.', 'The script reader for the actor.', maxw=1000)
h4('Cuffie dell\'attore e talkback', 'Actor\'s headphones and talkback')
p('**ADR > Cuffie dell\'attore e talkback** invia su una **seconda coppia di uscite** della scheda (serve una scheda con almeno 4 uscite) un mix per le cuffie dell\'attore, indipendente dal master degli altoparlanti.',
  '**ADR > Actor\'s headphones and talkback** sends a mix for the actor\'s headphones to a **second pair of outputs** of the interface (an interface with at least 4 outputs is needed), independent from the speakers\' master.')
fig('cuemix', 'Cuffie dell\'attore e talkback.', 'Actor\'s headphones and talkback.', maxw=900)
ul(('**Cuffie dell\'attore attive** e **Uscite cuffie** (la coppia di uscite).', '**Actor\'s headphones on** and **Headphone outputs** (the output pair).'),
   ('**MIX**, **BIP**, **TALKBACK** (dB): livelli del mix, dei bip e della voce del direttore nelle cuffie.', '**MIX**, **BEEP**, **TALKBACK** (dB): levels of the mix, the beeps and the director\'s voice in the headphones.'),
   ('**Abbassa il mix mentre il direttore parla**: durante il talkback il mix scende.', '**Lower the mix while the director speaks**: during talkback the mix goes down.'),
   ('**Microfono del direttore**: l\'ingresso del microfono; **TALKBACK (tieni premuto)**: parla nelle cuffie dell\'attore finché è premuto.', '**Director\'s microphone**: the microphone input; **TALKBACK (hold)**: talk into the actor\'s headphones while pressed.'),
   ('L\'indicatore **LIVELLO CUFFIE** in basso mostra il segnale inviato.', 'The **HEADPHONE LEVEL** meter at the bottom shows the signal being sent.'))
h4('Mix del direttore', 'Director mix')
p('Di norma l\'attore sente il master. Con **ADR > Mix del direttore per le cuffie (livelli per traccia)** si può invece dargli un mix tutto suo: *Mix personalizzato per le cuffie dell\'attore (invece del master)* e, per ogni traccia, il livello nelle cuffie dopo il fader (−80 = non si sente). Per esempio la guida e la musica alti e senza effetti. Il mix personalizzato si salva con la sessione e funziona solo con le cuffie dell\'attore attive.',
  'Normally the actor hears the master. With **ADR > Director mix for the headphones (levels per track)** you can instead give them a mix of their own: *Custom mix for the actor\'s headphones (instead of the master)* and, for each track, the level in the headphones after the fader (−80 = not heard). For example the guide and the music loud and with no effects. The custom mix is saved with the session and only works with the actor\'s headphones on.')
fig('director', 'Il mix del direttore per le cuffie.', 'The director mix for the headphones.', maxw=900)

# ======================================================================================================================
h2('Sincronia e montaggio', 'Sync and conforming')
h3('Allinea alla guida', 'Align to guide')
p('**Modifica > Allinea alla guida (sincronia automatica)** sposta i clip selezionati (o il take attivo del cue selezionato) fino a far coincidere il loro parlato con quello della traccia **Guida**. Il programma confronta l\'andamento del volume (non le parole) e cerca fino allo **spostamento massimo** indicato (predefinito 1500 ms); un risultato poco affidabile (somiglianza sotto 0,55) non viene applicato e viene segnalato. Con *Spostamento e adatta la durata del parlato* regola anche la durata (stretch) fra 80 % e 125 %.',
  '**Edit > Align to guide (automatic sync)** moves the selected clips (or the selected cue\'s active take) until their speech coincides with that of the **Guide** track. The program compares the volume envelope (not the words) and searches up to the **maximum offset** you set (default 1500 ms); an unreliable result (similarity below 0.55) is not applied and is reported. With *Offset and adapt the speech duration* it also adjusts the duration (stretch) between 80 % and 125 %.')
fig('dlg_align', 'Allinea alla guida.', 'Align to guide.', maxw=620)
h3('Allinea frase per frase', 'Align phrase by phrase')
p('**Modifica > Allinea alla guida frase per frase (Time Warp)** va oltre: dopo lo spostamento globale individua le **frasi** del take (le zone con parlato, separate da pause) e le abbina alle frasi della guida; poi con un Time Warp porta l\'inizio di ogni frase su quello della frase corrispondente, e anche la fine se la durata è simile (fra 85 % e 120 %). Le pause fra le frasi si accorciano o si allungano; il tono non cambia. Il rapporto indica quante frasi su quante sono state agganciate. Un solo undo per clip.',
  '**Edit > Align to guide phrase by phrase (Time Warp)** goes further: after the global shift it identifies the take\'s **phrases** (zones with speech, separated by pauses) and matches them to the guide\'s phrases; then with a Time Warp it brings the start of each phrase onto that of the matching phrase, and the end too if the length is similar (between 85 % and 120 %). The pauses between phrases get shorter or longer; pitch does not change. The report says how many phrases out of how many were matched. One undo per clip.')
fig('dlg_align_phrases', 'Allinea frase per frase.', 'Align phrase by phrase.', maxw=700)
h3('Separa dialoghi, musica ed effetti', 'Separate dialogue, music and effects')
p('**Modifica > Separa dialoghi / musica / effetti...** (anche dal menu del clip) separa l\'audio dei clip selezionati — di solito la **Guida**, cioè l\'audio originale del film — in **Dialoghi**, **Musica** ed **Effetti**. Serve per ottenere la colonna **M&E** internazionale da un film finito o per isolare i dialoghi originali. Funziona con un modello di intelligenza artificiale (Bandit v2, addestrato su audio cinematografico) che gira **sul tuo computer**.',
  '**Edit > Separate dialogue / music / effects...** (also from the clip menu) separates the audio of the selected clips — usually the **Guide**, i.e. the original audio of the film — into **Dialogue**, **Music** and **Effects**. It is used to obtain the international **M&E** track from a finished film or to isolate the original dialogue. It uses an artificial-intelligence model (Bandit v2, trained on cinema audio) that runs **on your computer**.')
fig('dlg_stems', 'La finestra della separazione.', 'The separation window.', maxw=620)
ul(('**Tre stem** crea tre tracce (Dialoghi, Musica, Effetti); **due stem** crea Dialoghi e M&E (musica ed effetti insieme, pronto per la consegna).', '**Three stems** creates three tracks (Dialogue, Music, Effects); **two stems** creates Dialogue and M&E (music and effects together, ready for delivery).'),
   ('**Qualità alta** usa una sovrapposizione maggiore tra i blocchi: è circa il 50% più lenta. **Silenzia i clip originali** lascia l\'originale al suo posto ma muto.', '**High quality** uses more overlap between the blocks: it is about 50% slower. **Mute the original clips** leaves the original in place but muted.'),
   ('Il risultato sono **nuove tracce con il ruolo giusto** (Dialoghi, M&E, Effetti) con i clip nella stessa posizione degli originali, in **un solo passo di annullamento**. I file WAV a 24 bit stanno nella cartella dei media, sotto *Separati*. **Dialoghi + Musica + Effetti = originale**: nulla si perde.', 'The result is **new tracks with the right role** (Dialogue, M&E, Effects) with the clips in the same position as the originals, in **a single undo step**. The 24-bit WAV files are in the media folder, under *Separati*. **Dialogue + Music + Effects = original**: nothing is lost.'),
   ('La **prima volta** il programma scarica il motore di separazione (circa 110 MB, serve internet); poi funziona **offline**. Una barra mostra l\'avanzamento e permette di annullare. Il tempo è circa un terzo della durata dell\'audio su un Mac Apple Silicon: conviene lavorare per scene o rulli.', 'The **first time** the program downloads the separation engine (about 110 MB, internet needed); after that it works **offline**. A bar shows the progress and lets you cancel. The time is about a third of the audio\'s duration on an Apple Silicon Mac: it is best to work by scenes or reels.'))
h3('Dividi le voci in maschile e femminile', 'Split voices into male and female')
p('Nella finestra della separazione la casella **Dividi i dialoghi in voce maschile e voce femminile** fa nascere, al posto della sola traccia Dialoghi, due tracce: **voce maschile** e **voce femminile**. Lo stesso si può fare dopo, sui clip della traccia Dialoghi creata dalla separazione, con **Modifica > Dividi le voci in maschile e femminile...** (anche dal menu del clip). Il riconoscimento funziona **solo sui Dialoghi separati**, cioè sul parlato pulito: sugli altri clip il comando non è attivo. Il programma misura il **tono** della voce (F0), frase per frase, e assegna ogni frase a una delle due tracce; i tagli cadono a metà delle pause, quindi **le due tracce insieme ridanno esattamente l\'originale**. I clip puntano allo stesso audio (nessun file nuovo) e tutto è un solo passo di **Annulla**. Le frasi di cui non è sicuro hanno un **?** all\'inizio del nome del clip: controllale e, se serve, trascinale sull\'altra traccia. Se nei clip c\'è una sola voce, non viene creato nulla.',
  'In the separation window the **Split the dialogue into male and female voice** box creates, instead of the single Dialogue track, two tracks: **male voice** and **female voice**. You can also do it later, on the clips of the Dialogue track created by the separation, with **Edit > Split voices into male and female...** (also from the clip menu). Recognition works **only on separated Dialogue**, i.e. on clean speech: on other clips the command is not active. The program measures the voice **pitch** (F0), phrase by phrase, and assigns each phrase to one of the two tracks; the cuts fall in the middle of the pauses, so **the two tracks together give back exactly the original**. The clips point to the same audio (no new files) and everything is a single **Undo** step. Phrases it is not sure about have a **?** at the start of the clip name: check them and, if needed, drag them to the other track. If the clips contain a single voice, nothing is created.')
note('Il riconoscimento è dal tono, non da un modello neurale: va bene con voci adulte normali, ma può sbagliare con bambini, voci molto gravi o molto acute, sussurri e grida. **Non separa due persone che parlano insieme**: la frase va alla voce dominante.',
     'The recognition is by pitch, not by a neural model: it works well with normal adult voices, but it can be wrong with children, very low or very high voices, whispers and shouts. **It does not separate two people speaking together**: the phrase goes to the dominant voice.')
note('La separazione non è perfetta: musica molto «vocale», riverberi lunghi o brusio di folla possono restare in parte nei dialoghi. Il modello è multilingua (non c\'è una versione solo italiana). Controlla sempre a orecchio. Il modello ha licenza CC BY-SA 4.0: i dettagli sono in *Aiuto > Licenze di terze parti*.',
     'Separation is not perfect: very vocal music, long reverbs or crowd chatter can partly remain in the dialogue. The model is multilingual (there is no Italian-only version). Always check by ear. The model is licensed CC BY-SA 4.0: details are in *Help > Third-party licenses*.')
h3('Ducking automatico', 'Automatic ducking')
p('**Traccia > Ducking automatico del fondo sotto i dialoghi** abbassa **M&E ed Effetti** quando parlano i **Dialoghi**, scrivendo l\'automazione del volume (annullabile). Si scelgono quanto abbassare (dB), la soglia del dialogo, i tempi di **discesa** e di **risalita**.',
  '**Track > Automatic ducking of the background under the dialogue** lowers **M&E and Effects** when the **Dialogue** speaks, writing the volume automation (undoable). You choose how much to lower (dB), the dialogue threshold, and the **fall** and **rise** times.')
fig('dlg_ducking', 'Ducking automatico.', 'Automatic ducking.', maxw=620)
h3('Livella il volume', 'Level the volume')
p('**Traccia > Livella il volume della traccia (automazione)** (anche dal menu della traccia) analizza il livello percepito delle tracce selezionate e scrive sul loro volume un\'automazione che lo rende uniforme, come farebbe a mano un fonico con il fader (\"vocal rider\"). Il livello e\' misurato secondo BS.1770 sulla traccia **dopo EQ, compressore e plug-in**, a finestre di 400 ms. Si sceglie l\'**Obiettivo**: *Automatico* (il livello mediano del parlato della traccia: si uniforma senza alzare o abbassare il totale) oppure un valore in LUFS; il **massimo aumento** e la **massima riduzione** (predefiniti 9 dB); la **velocita\' di reazione** (Lenta, Media, Rapida). Il parlato si riconosce dal **tono della voce** e dalla distanza dal **fondo** della traccia: il fruscio e il rumore della stanza non hanno tono e vengono trattati come pause, quindi **non vengono mai alzati**. Nelle **pause** vere (almeno 0,6 s) il volume **si abbassa** (predefinito -12 dB rispetto al fader; si può scegliere 6, 12 o 20 dB oppure *Lascia il livello della frase*): fruscio, ronzii e rumori di fondo calano, ma senza buchi. Dopo la fine della frase il volume aspetta 0,25 s (per non tagliare code e riverbero), scende in 0,3 s e risale 0,25 s prima della frase successiva, così l\'attacco resta intatto e l\'aumento non porta i picchi oltre -1 dBFS. Se sul righello e\' selezionato un intervallo, solo quello viene livellato. La curva ha pochi punti (circa uno o due al secondo), si vede e si modifica nella corsia del volume, ed e\' un solo passo di **Annulla**. Al termine una finestra riporta, per ogni traccia, la variazione di livello prima e dopo. Il volume automatizzato non puo\' superare +6 dB: se serve di piu\', abbassa prima il fader della traccia. Non sostituisce un compressore: livella le frasi, non i singoli picchi.',
  '**Track > Level the track volume (automation)** (also in the track menu) analyses the perceived level of the selected tracks and writes a volume automation that evens it out, just as an engineer would do by hand with the fader (a \"vocal rider\"). The level is measured to BS.1770 on the track **after EQ, compressor and plug-ins**, in 400 ms windows. You choose the **Target**: *Automatic* (the track\'s median speech level: it evens out without raising or lowering the whole) or a value in LUFS; the **maximum boost** and **maximum cut** (9 dB by default); and the **reaction speed** (Slow, Medium, Fast). Speech is recognised from the **voice pitch** and from the distance from the track\'s **noise floor**: hiss and room noise have no pitch and are treated as pauses, so **they are never raised**. In real **pauses** (at least 0.6 s) the volume is **lowered** (by default -12 dB relative to the fader; you can choose 6, 12 or 20 dB or *Keep the phrase level*): hiss, hum and background noise go down, but without holes. After the end of a phrase the volume waits 0.25 s (so as not to cut tails and reverb), falls in 0.3 s and rises again 0.25 s before the next phrase, so the attack stays intact and the boost never takes the peaks above -1 dBFS. If a range is selected on the ruler, only that range is levelled. The curve has few points (about one or two per second), shows and can be edited in the volume lane, and is a single **Undo** step. Afterwards a window reports, for each track, the level variation before and after. Automated volume cannot exceed +6 dB: if you need more, lower the track fader first. It does not replace a compressor: it levels phrases, not individual peaks.')
h3('ReConform: un nuovo montaggio', 'ReConform: a new cut')
p('Quando arriva un nuovo montaggio del film, **Modifica > ReConform** riporta audio, cue e marker sulle nuove posizioni a partire dagli **EDL** (CMX3600) del vecchio e del nuovo montaggio, con gli stessi nomi di bobina. Il materiale tolto viene tagliato, i cue che cadono nel tolto diventano «Da rifare» con la nota «Fuori dal nuovo montaggio», il materiale nuovo resta senza audio; si possono mettere marker sui punti di modifica. Una **Anteprima** testuale elenca prima i segmenti spostati, i secondi tolti e inseriti, i cue toccati e gli avvisi; **Applica** esegue tutto in un solo passo di undo (prima salva una versione di sicurezza, se lo chiedi). Il video nuovo si importa a parte.',
  'When a new cut of the film arrives, **Edit > ReConform** moves audio, cues and markers to their new positions starting from the **EDLs** (CMX3600) of the old and new cut, with the same reel names. Removed material is cut, cues that fall in the removed part become "To redo" with the note "Outside the new cut", new material stays without audio; markers can be put on the edit points. A text **Preview** first lists the shifted segments, the seconds removed and inserted, the cues touched and the warnings; **Apply** does everything in one undo step (first saving a safety version, if you ask). The new video is imported separately.')
fig('dlg_reconform', 'ReConform.', 'ReConform.', maxw=1100)
note('Gli EDL con dissolvenze o wipe sono trattati come tagli a metà transizione; le rimappature di velocità non sono supportate.',
     'EDLs with dissolves or wipes are treated as cuts at mid-transition; speed remaps are not supported.')
h3('Sincronia esterna MTC', 'External sync MTC')
p('**Trasporto > Sincronia esterna (MTC)** fa seguire il trasporto a un timecode **MIDI (MTC)** esterno: quando arriva il timecode il programma si posiziona e parte; se si ferma, si ferma; se la deriva supera 2 fotogrammi si riallinea. Si sceglie l\'ingresso MIDI e un offset in millisecondi; la posizione zero della sessione corrisponde all\'inizio sessione. Riceve MTC: non lo genera e non legge l\'LTC.',
  '**Transport > External sync (MTC)** makes the transport follow an external **MIDI timecode (MTC)**: when timecode arrives the program locates and starts; if it stops, it stops; if the drift exceeds 2 frames it realigns. You choose the MIDI input and an offset in milliseconds; the session\'s zero position corresponds to the session start. It receives MTC: it does not generate it and does not read LTC.')
fig('mtc', 'Sincronia esterna MTC.', 'External sync MTC.', maxw=900)

# ======================================================================================================================
h2('Esportazione e consegna', 'Export and delivery')
h3('Esportare il mix', 'Exporting the mix')
p('**File > Esporta audio** (Cmd + E) scrive il mix (o gli stem) in un file. L\'esportazione è offline (più veloce del tempo reale) e usa gli stessi inserti, il PDC e il limiter del master.',
  '**File > Export audio** (Cmd + E) writes the mix (or the stems) to a file. The export is offline (faster than real time) and uses the same inserts, the PDC and the master limiter.')
fig('dlg_export', 'File > Esporta audio.', 'File > Export audio.', maxw=760)
table((('Voce', 'Item'), ('Che cosa fa', 'What it does')),
      (('**Preset**', '**Preset**'), ('Master WAV 24 bit, Broadcast EBU R128 (−23 LUFS), Streaming e social (−14 LUFS), Podcast (−16 LUFS, WAV 16 bit), CD (16 bit, 44,1 kHz, picco −0,3 dB), Stem, Consegna doppiaggio, TV USA ATSC A/85 (−24 LUFS, −2 dBTP), Streaming dialoghi (−27 LUFS, −2 dBTP).', 'Master WAV 24 bit, Broadcast EBU R128 (−23 LUFS), Streaming and social (−14 LUFS), Podcast (−16 LUFS, WAV 16 bit), CD (16 bit, 44.1 kHz, peak −0.3 dB), Stems, Dubbing delivery, US TV ATSC A/85 (−24 LUFS, −2 dBTP), Streaming dialogue (−27 LUFS, −2 dBTP).')),
      (('**Formato / Profondità / Frequenza**', '**Format / Bit depth / Sample rate**'), ('WAV, AIFF, FLAC o **MP3** (320 kbps, per ascolto e revisione; al massimo 48 kHz); 16, 24 o 32 bit; frequenza della sessione, 44,1, 48, 88,2 o 96 kHz.', 'WAV, AIFF, FLAC or **MP3** (320 kbps, for listening and review; 48 kHz at most); 16, 24 or 32 bit; the session rate, 44.1, 48, 88.2 or 96 kHz.')),
      (('**Intervallo**', '**Range**'), ('Tutta la sessione, oppure l\'intervallo scelto sul righello (barra di esportazione).', 'The whole session, or the range chosen on the ruler (export bar).')),
      (('**Normalizzazione**', '**Normalisation**'), ('Nessuna; al picco (valore in dBFS); oppure al **loudness** (obiettivo in LUFS): il programma misura e porta il programma all\'obiettivo; se superasse il tetto di true-peak interviene un limiter trasparente.', 'None; to peak (value in dBFS); or to **loudness** (target in LUFS): the program measures and brings the programme to the target; if it exceeded the true-peak ceiling a transparent limiter steps in.')),
      (('**Dither a 16 bit**', '**Dither at 16 bit**'), ('Un leggero dither contro la distorsione di quantizzazione.', 'A light dither against quantisation distortion.')),
      (('**Un file per traccia (stem)**', '**One file per track (stems)**'), ('Un file per ogni traccia con clip, dopo fader e inserti, senza limiter e plug-in del master; i file sono allineati fra loro.', 'One file for every track with clips, after fader and inserts, without the master limiter and plug-ins; the files are aligned with each other.')),
      (('**Pacchetto di consegna**', '**Delivery package**'), ('In una sola esportazione: il MIX (con il bus master) e uno stem per ogni bus di ruolo (Dialoghi, M&E, Effetti), tutti con lo stesso guadagno, più un **rapporto HTML** con picco, true-peak e loudness di ogni file.', 'In one export: the MIX (with the master bus) and one stem for every role bus (Dialogue, M&E, Effects), all with the same gain, plus an **HTML report** with the peak, true-peak and loudness of every file.')),
      (('**Escludi la traccia Guida**', '**Exclude the Guide track**'), ('La traccia Guida (dialogo originale) non entra nell\'esportazione.', 'The Guide track (original dialogue) is not included in the export.')))
h3('Esportazione in batch', 'Batch export')
p('**File > Esportazione in batch** esporta in una sola volta più formati: si spuntano i preset (per esempio Broadcast, Streaming, Stem, Consegna doppiaggio, TV USA) e ognuno finisce in una sottocartella, o in un file con il nome del preset, nella cartella scelta.',
  '**File > Batch export** exports several formats in one go: tick the presets (for example Broadcast, Streaming, Stems, Dubbing delivery, US TV) and each goes into a subfolder, or into a file named after the preset, in the folder you choose.')
fig('dlg_batch_export', 'L\'esportazione in batch.', 'Batch export.', maxw=900)
h3('Pacchetti e archivi', 'Packages and archives')
ul(('**Esporta il pacchetto della sessione (Clip Package)** (File): copia in una cartella la sessione e tutti i file (con percorsi relativi) per passarla a un collega; si riapre su un altro computer senza ricollegare nulla.', '**Export the session package (Clip Package)** (File): copies into a folder the session and all the files (with relative paths) to pass to a colleague; it reopens on another computer without relinking anything.'),
   ('**Esporta video con il mix** (Maiusc + Cmd + E): scrive un video di revisione con il mix audio al posto dell\'audio originale; con la sovrimpressione (burn-in) di timecode e battuta (su macOS).', '**Export video with mix** (Shift + Cmd + E): writes a review video with the mix audio in place of the original audio; with the timecode and line overlay (burn-in) (on macOS).'),
   ('**Archivio di tracce**: vedi *Tracce*.', '**Track archive**: see *Tracks*.'))
tip('Prima di consegnare esegui **File > Controlla la sessione**: segnala tracce senza ruolo (che comparirebbero solo nel MIX), cue da registrare o da rifare, media mancanti.',
    'Before delivering run **File > Check the session**: it reports tracks without a role (which would appear only in the MIX), cues to record or redo, missing media.')

